129	      try {
130	        server = await startServer(dir);
131	        const file = ideasFile(server);
132	        const tmpFile = `${file}.tmp`;
133	
134	        // 服务已正常启动后，在进程之外把存储改成无法读取的内容。
135	        writeFileSync(file, corrupt.content, 'utf8');
136	        const before = readFileSync(file);
137	        assert.equal(before.toString('utf8'), corrupt.content);
138	
139	        // 提交一条三字段均合法的新意见：必须 500，使用现有 error 说明，
140	        // 响应不能带表示保存成功的 idea，也不能归为字段填错的 400。
141	        const post1 = await postNewIdea(server);
142	        assert.equal(post1.status, 500);
143	        assert.match(post1.contentType ?? '', /application\/json/);
144	        assert.ok(post1.data && typeof post1.data === 'object');
145	        assert.equal(post1.data.error, '无法读取已有意见数据，未保存新意见');
146	        assert.equal(Object.prototype.hasOwnProperty.call(post1.data, 'idea'), false);
147	
148	        // 最关键的保护：拒绝保存后原有文字一个字节都不能变，
149	        // 不能被重写为空数组、换一种格式整理，或替换成只含新意见的列表。
150	        assert.ok(readFileSync(file).equals(before), '提交被拒绝后存储内容被改动');
151	        assert.equal(existsSync(tmpFile), false, '拒绝保存后不应留下临时文件');
152	
153	        // 同样的异常条件下查询也必须是现有的 500 错误，不能返回成功的空列表。
154	        const get1 = await getIdeas(server);
155	        assert.equal(get1.status, 500);
156	        assert.deepEqual(get1.data, { error: 'unable to read ideas' });
157	        assert.ok(readFileSync(file).equals(before), '查询失败后存储内容被改动');
158	
159	        // 重复的提交与查询再次失败：任何一次失败请求都不能触发写入或“自愈”式重写。
160	        const post2 = await postNewIdea(server);
161	        assert.equal(post2.status, 500);
162	        assert.equal(post2.data.error, '无法读取已有意见数据，未保存新意见');
163	        assert.equal(Object.prototype.hasOwnProperty.call(post2.data, 'idea'), false);
164	        const get2 = await getIdeas(server);
165	        assert.equal(get2.status, 500);
166	        assert.deepEqual(get2.data, { error: 'unable to read ideas' });
167	        assert.ok(readFileSync(file).equals(before), '再次失败后存储内容被改动');
168	        assert.equal(existsSync(tmpFile), false);
169	
170	        // 正常停止并用同一数据目录重启：启动过程也不能把无法读取的内容重置为空数组。
171	        await server.stop();
172	        server = undefined;
173	        server = await startServer(dir);
174	        assert.ok(readFileSync(file).equals(before), '重启后原有存储内容被改动');
175	
176	        const getAfterRestart = await getIdeas(server);
177	        assert.equal(getAfterRestart.status, 500);
178	        assert.deepEqual(getAfterRestart.data, { error: 'unable to read ideas' });
179	
180	        const postAfterRestart = await postNewIdea(server);
181	        assert.equal(postAfterRestart.status, 500);
182	        assert.equal(postAfterRestart.data.error, '无法读取已有意见数据，未保存新意见');
183	        assert.equal(Object.prototype.hasOwnProperty.call(postAfterRestart.data, 'idea'), false);
