  // UTF-8 规则的编码，无论出现在标题、详细说明、使用场景还是其他位置，都让整份数据
  // 读取失败——不替换、不忽略、不只读取其中的正常片段。
  const raw = readFileSync(dataFile);
  let text: string;
  try {
