  Buffer.from('替换符","description":"中文\n换行 与表情 😀","scenario":"","createdAt":"2024-01-01T00:00:00.000Z"}]\n','utf8'),
]));

const child = spawn(process.execPath,
  ['/opt/gsb-production/workspaces/coco/prod-19/A/task026/server.ts','serve','--host','127.0.0.1','--port','18801','--data-dir',dir],
  { stdio: ['ignore','pipe','pipe'] });
